import { chromium } from 'playwright-core';
const S = 'C:/Users/Adnan/AppData/Local/Temp/claude/c--Users-Adnan-ERP/c6e635ea-3f80-4c28-9024-d0f98e016545/scratchpad/state-' + process.argv[2] + '.json';
const browser = await chromium.launch({ executablePath: 'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe' });
const page = await (await browser.newContext({ viewport: { width: 1440, height: 900 }, storageState: S })).newPage();
page.on('pageerror', e => console.log('pageerror:', e.stack.slice(0,500)));
page.on('response', async r => { if (r.url().includes('/api/')) console.log('HTTP', r.status(), r.url().replace('http://localhost:8000','')); });
await page.goto('http://localhost:3000' + process.argv[3], { waitUntil: 'networkidle' });
await page.waitForTimeout(8000);
console.log((await page.innerText('main')).slice(0,600));
await page.screenshot({ path: 'C:/Users/Adnan/AppData/Local/Temp/claude/c--Users-Adnan-ERP/c6e635ea-3f80-4c28-9024-d0f98e016545/scratchpad/dbg.png' });
await browser.close();
